SELECT FROM red_packet rp JOIN employee e ON e.id = rp.employee_id JOIN employee s ON s.id = rp.sender_id
AND rp.employee_id = #{employeeId}
ORDER BY rp.created_at DESC LIMIT #{limit}

SELECT COALESCE(SUM(amount), 0)
FROM red_packet
WHERE employee_id = #{employeeId} AND DATE_FORMAT(created_at, '%Y-%m') = #{month}
